import{c as i,$ as l,Q as t,j as r,g as o,o as s,n as c,m as d}from"./chunks/framework.Ce_49mA8.js";const q=JSON.parse('{"title":"Резервное копирование и безопасность данных","description":"Автоматические снимки поколений, ручной экспорт в ZIP и CSV, селективное восстановление и устойчивость базы данных в ОмниКрафт ЕРП.","frontmatter":{"title":"Резервное копирование и безопасность данных","description":"Автоматические снимки поколений, ручной экспорт в ZIP и CSV, селективное восстановление и устойчивость базы данных в ОмниКрафт ЕРП.","order":17,"datePublished":"2026-11-14","dateModified":"2026-11-22"},"headers":[],"relativePath":"ru/docs/backups.md","filePath":"ru/docs/backups.md","lastUpdated":1795305600000}'),n={name:"ru/docs/backups.md"},h={id:"резервное-копирование-и-безопасность-данных",tabindex:"-1"};function p(u,a,m,_,b,g){const e=l("DocIcon");return t(),r("div",null,[o("h1",h,[s(e,{name:"database"}),a[0]||(a[0]=c(" Резервное копирование и безопасность данных ",-1)),a[1]||(a[1]=o("a",{class:"header-anchor",href:"#резервное-копирование-и-безопасность-данных","aria-label":'Permalink to "Резервное копирование и безопасность данных"'},"​",-1))]),a[2]||(a[2]=d('<p>ОмниКрафт ЕРП спроектирован по канонам автономного локального программного обеспечения. База данных, технологические карты, себестоимость изделий и балансы счетов хранятся непосредственно на вашем рабочем компьютере, исключая передачу конфиденциальной коммерческой информации на сторонние облачные серверы.</p><p>Локальный суверенитет обеспечивает полную независимость от интернета, но требует дисциплины в защите физических файлов. Чтобы обезопасить бизнес от поломок накопителей, случайного удаления или повреждения операционной системы, в программу встроен многоуровневый комплекс автоматического и ручного резервного копирования.</p><hr><h2 id="автоматические-теневые-архивы" tabindex="-1">Автоматические теневые архивы <a class="header-anchor" href="#автоматические-теневые-архивы" aria-label="Permalink to &quot;Автоматические теневые архивы&quot;">​</a></h2><p>В фоновом режиме программа реализует отраслевую стратегию ротации архивов по принципу поколений («дед — отец — сын»). Создание снимков происходит асинхронно, без подвисания интерфейса и без прерывания текущих расчетов мастера.</p><h3 id="_1-архивы-при-запуске-программы" tabindex="-1">1. Архивы при запуске программы <a class="header-anchor" href="#_1-архивы-при-запуске-программы" aria-label="Permalink to &quot;1. Архивы при запуске программы&quot;">​</a></h3><p>При каждом открытии ОмниКрафт ЕРП проверяет системный календарь. Если наступил новый расчетный период, система формирует компактный архив всей экосистемы без тяжелых медиафайлов:</p><ul><li><strong>Ежедневный снимок</strong> (<code>auto_daily.zip</code>) — создается при первом старте программы в текущие сутки.</li><li><strong>Еженедельный снимок</strong> (<code>auto_weekly.zip</code>) — фиксирует состояние учета на начало новой недели.</li><li><strong>Ежемесячный снимок</strong> (<code>auto_monthly.zip</code>) — сохраняет контрольный слепок на первое число каждого месяца.</li><li><strong>Ежегодный снимок</strong> (<code>auto_yearly.zip</code>) — долгосрочный архив для годовой финансовой отчетности.</li></ul><h3 id="_2-архивы-при-завершении-работы" tabindex="-1">2. Архивы при завершении работы <a class="header-anchor" href="#_2-архивы-при-завершении-работы" aria-label="Permalink to &quot;2. Архивы при завершении работы&quot;">​</a></h3><p>Когда мастер закрывает приложение, программа скрывает главное окно и мгновенно выполняет регламентные процедуры завершения:</p><ol><li><strong>Оптимизация индексов:</strong> Выполняется команда <code>PRAGMA optimize;</code>, которая собирает внутреннюю статистику использования таблиц для ускорения будущих поисковых запросов к базе данных.</li><li><strong>Ротационный каскад трех слотов:</strong> Программа поддерживает скользящую тройку последних завершений работы — <code>auto_close_1.zip</code>, <code>auto_close_2.zip</code> и <code>auto_close_3.zip</code>. При каждом закрытии более старые копии сдвигаются на шаг назад, сохраняя доступ к трем последним рабочим сессиям.</li><li><strong>Очистка служебного мусора:</strong> Автоматический сборщик удаляет временные файлы предпросмотра печати ценников и накладных.</li></ol><h3 id="_3-предохранительные-снимки-перед-опасными-операциями" tabindex="-1">3. Предохранительные снимки перед опасными операциями <a class="header-anchor" href="#_3-предохранительные-снимки-перед-опасными-операциями" aria-label="Permalink to &quot;3. Предохранительные снимки перед опасными операциями&quot;">​</a></h3><p>Перед выполнением любых необратимых действий программа принудительно создает теневую копию базы данных:</p><ul><li>Перед процедурой <strong>«Сброс учета»</strong> (очисткой операционных журналов);</li><li>Перед <strong>«Полным сбросом до заводских настроек»</strong>;</li><li>Перед автоматическим обновлением структуры таблиц при переходе на новую версию программы.</li></ul><h3 id="_4-расположение-каталога-резервных-копии" tabindex="-1">4. Расположение каталога резервных копий <a class="header-anchor" href="#_4-расположение-каталога-резервных-копии" aria-label="Permalink to &quot;4. Расположение каталога резервных копий&quot;">​</a></h3><p>Все автоматические снимки сохраняются в защищенной системной папке программы:</p><ul><li><strong>Windows:</strong> <code>%APPDATA%\\OmniCraft\\backups\\</code> (обычно <code>C:\\Users\\&lt;Имя&gt;\\AppData\\Roaming\\OmniCraft\\backups\\</code>);</li><li><strong>Linux:</strong> <code>~/.config/OmniCraft/backups/</code>.</li></ul><div class="tip custom-block"><p class="custom-block-title">Цеховой совет по защите архивов</p><p>Настройте автоматическую синхронизацию папки <code>backups</code> с внешним накопителем или защищенным сетевым хранилищем. В случае внезапного выхода из строя системного диска вы восстановите мастерскую за считанные минуты.</p></div><hr><h2 id="ручнои-экспорт-данных" tabindex="-1">Ручной экспорт данных <a class="header-anchor" href="#ручнои-экспорт-данных" aria-label="Permalink to &quot;Ручной экспорт данных&quot;">​</a></h2><p>Для переноса данных на новый компьютер, отправки копии бухгалтеру или создания архивного слепка используйте пункт меню <strong>«Файл» ➔ «Экспорт данных...»</strong>. Система предоставляет два формата выгрузки.</p><h3 id="_1-полная-резервная-копия-системы-в-архиве-zip" tabindex="-1">1. Полная резервная копия системы в архиве ZIP <a class="header-anchor" href="#_1-полная-резервная-копия-системы-в-архиве-zip" aria-label="Permalink to &quot;1. Полная резервная копия системы в архиве ZIP&quot;">​</a></h3><p>Создает упакованный архив всей рабочей экосистемы. В модальном окне мастер может гибко отметить необходимые компоненты:</p><ul><li><code>[x] Основные данные учета</code> — база <code>omnicraft_erp.db</code> (каталог сырья, калькулятор, готовая продукция, чеки, касса ДДС);</li><li><code>[x] Рабочие пространства</code> — изолированные базы данных личных финансов (<code>workspaces/*.db</code>) и системный реестр <code>workspaces.json</code>;</li><li><code>[x] Фотографии, медиафайлы и документы техкарт</code> — изображения сырья, оборудования и готовых изделий, а также файлы из техкарт;</li><li><code>[x] База знаний и навыки ИИ</code> — библиотека прикладных сценариев, цеховой манифест и выученные ассистентом правила;</li><li><code>[x] История переписок и проекты чатов</code> — контекстная база диалогов ассистента <code>ai_context.db</code>.</li></ul><p>В корень каждого архива автоматически записывается файл манифеста <code>backup_manifest.json</code>, содержащий версию схемы, контрольные суммы и перечень компонентов.</p><div class="tip custom-block"><p class="custom-block-title">Мгновенный облегченный экспорт</p><p>База диалогов с нейросетью физически вынесена в отдельный файл <code>ai_context.db</code>. Если снять галочку с компонента «История переписок и проекты чатов», экспорт выполняется в несколько раз быстрее и создает компактный файл, оптимальный для регулярной отправки по почте.</p></div><h3 id="_2-таблицы-текущего-пространства-в-формате-csv" tabindex="-1">2. Таблицы текущего пространства в формате CSV <a class="header-anchor" href="#_2-таблицы-текущего-пространства-в-формате-csv" aria-label="Permalink to &quot;2. Таблицы текущего пространства в формате CSV&quot;">​</a></h3><p>Пункт <strong>«Таблицы текущего пространства (.zip с CSV)»</strong> выполняет сплошную выгрузку всех таблиц активного пространства в виде раздельных текстовых файлов с разделителями-запятыми, упаковывая их в общий архив.</p><ul><li><strong>Независимый финансовый аудит:</strong> Таблицы формата CSV открываются в любых табличных редакторах (Яндекс Документы, Excel, LibreOffice Calc) для глубокого анализа, сверки или построения кастомных сводных отчетов.</li><li><strong>Цифровой парашют:</strong> Даже если файл базы данных получит аппаратные повреждения секторов жесткого диска, текстовые таблицы CSV всегда можно прочитать стандартным блокнотом и восстановить каждую позицию.</li></ul><hr><h2 id="восстановление-данных-и-откат-состояния" tabindex="-1">Восстановление данных и откат состояния <a class="header-anchor" href="#восстановление-данных-и-откат-состояния" aria-label="Permalink to &quot;Восстановление данных и откат состояния&quot;">​</a></h2><p>Процедуры восстановления вызываются через пункты системного меню <strong>«Файл» ➔ «Импорт данных...»</strong> и <strong>«Файл» ➔ «Восстановить из автосохранения...»</strong>.</p><h3 id="_1-восстановление-из-автосохранения-через-меню-отката" tabindex="-1">1. Восстановление из автосохранения через меню отката <a class="header-anchor" href="#_1-восстановление-из-автосохранения-через-меню-отката" aria-label="Permalink to &quot;1. Восстановление из автосохранения через меню отката&quot;">​</a></h3><p>Пункт меню <strong>«Восстановить из автосохранения...»</strong> открывает хронологический реестр встроенных снимков. Каждая точка отката снабжена наглядной карточкой с указанием даты фиксации, точного времени и физического размера архива:</p><ol><li>Выберите подходящий снимок из списка («Закрытие программы (Последнее)», «Ежедневная копия» или архив за прошлую неделю);</li><li>Нажмите кнопку восстановления и подтвердите действие в модальном диалоге;</li><li>Программа распакует базу, проверит контрольные структуры и выполнит чистый перезапуск приложения.</li></ol><h3 id="_2-селективное-восстановление-из-архивного-фаила" tabindex="-1">2. Селективное восстановление из архивного файла <a class="header-anchor" href="#_2-селективное-восстановление-из-архивного-фаила" aria-label="Permalink to &quot;2. Селективное восстановление из архивного файла&quot;">​</a></h3><p>При выборе пункта <strong>«Восстановление системы из бэкапа (.zip)»</strong> в меню импорта программа предварительно считывает служебный манифест <code>backup_manifest.json</code> из выбранного файла и открывает диалог выборочной загрузки:</p><ul><li>Мастер может восстановить только номенклатуру склада и справочники рецептов, оставив текущие диалоги ассистента нетронутыми;</li><li>Можно выборочно накатить каталог рабочих пространств, не затрагивая основную коммерческую базу;</li><li>Встроенный верификатор проверяет совместимость версий и блокирует поврежденные или чужеродные архивы.</li></ul><h3 id="_3-восстановление-из-бинарнои-базы-данных" tabindex="-1">3. Восстановление из бинарной базы данных <a class="header-anchor" href="#_3-восстановление-из-бинарнои-базы-данных" aria-label="Permalink to &quot;3. Восстановление из бинарной базы данных&quot;">​</a></h3><p>Если у вас есть прямой файл базы данных с расширением <code>.db</code> (например, выгруженный вручную файл <code>omnicraft_erp.db</code>), программа производит безопасную замену текущей рабочей базы с автоматической перепроверкой целостности таблиц и последующим перезапуском.</p><h3 id="_4-импорт-таблиц-пространства-из-архива-csv" tabindex="-1">4. Импорт таблиц пространства из архива CSV <a class="header-anchor" href="#_4-импорт-таблиц-пространства-из-архива-csv" aria-label="Permalink to &quot;4. Импорт таблиц пространства из архива CSV&quot;">​</a></h3><p>При выборе <strong>«Импорт таблиц пространства (.zip с CSV)»</strong> система распаковывает текстовые файлы, очищает существующие таблицы активного пространства и построчно заполняет их данными из архива. Каждый входящий поток проходит строгую валидацию типов полей, исключая синтаксические сбои и повреждение связей между таблицами.</p><div class="danger custom-block"><p class="custom-block-title">Критическое правило: Импорт полностью перезаписывает базу</p><p>Процедура импорта <strong>не объединяет</strong> записи, а целиком замещает текущее состояние программы состоянием из резервной копии. Все операции, чеки и правки, сделанные после даты создания загружаемого бэкапа, будут безвозвратно утрачены. Всегда создавайте свежий ручной экспорт перед накатом старого архива!</p></div><hr><h2 id="инженерная-надежность-и-защита-базы-данных-под-капотом" tabindex="-1">Инженерная надежность и защита базы данных под капотом <a class="header-anchor" href="#инженерная-надежность-и-защита-базы-данных-под-капотом" aria-label="Permalink to &quot;Инженерная надежность и защита базы данных под капотом&quot;">​</a></h2><p>Помимо резервных копий, само ядро хранения данных ОмниКрафт ЕРП спроектировано с расчетом на работу в условиях нестабильного цехового электропитания и аппаратных сбоев.</p><h3 id="_1-журналирование-с-упреждающеи-записью" tabindex="-1">1. Журналирование с упреждающей записью <a class="header-anchor" href="#_1-журналирование-с-упреждающеи-записью" aria-label="Permalink to &quot;1. Журналирование с упреждающей записью&quot;">​</a></h3><p>Все базы данных программы функционируют в специальном режиме журналирования с упреждающей записью (режим ВАЛ):</p><ul><li>Любое изменение (создание накладной, проведение чека, списание партии сырья) сначала атомарно фиксируется в отдельном скоростном файле журнала упреждающей записи.</li><li>Только после гарантированной фиксации на диске данные переносятся в основное хранилище базы.</li><li><strong>Устойчивость к внезапному обесточиванию:</strong> Если посреди записи операции в мастерской выключится свет или зависнет операционная система, повреждения базы не произойдет. При следующем старте движок базы данных мгновенно прочитает журнал и либо завершит операцию, либо бесследно откатит ее до безопасного состояния.</li></ul><h3 id="_2-атомарная-подмена-фаилов-и-дисковыи-мьютекс" tabindex="-1">2. Атомарная подмена файлов и дисковый мьютекс <a class="header-anchor" href="#_2-атомарная-подмена-фаилов-и-дисковыи-мьютекс" aria-label="Permalink to &quot;2. Атомарная подмена файлов и дисковый мьютекс&quot;">​</a></h3><p>При создании автоматических фоновых снимков программа исключает повреждение рабочего файла базы:</p><ul><li>Операция синхронизируется через межпоточный мьютекс файлового ввода-вывода (<code>WORKSPACE_IO_MUTEX</code>), предотвращая одновременную запись данных и чтение архиватором.</li><li>Снимок сначала формируется во временный файл с расширением <code>.tmp</code> и лишь после успешного сжатия атомарно заменяет целевой архив через системный вызов <code>os.replace</code>.</li></ul><h3 id="_3-защита-от-многопоточных-блокировок-и-взаимного-ожидания" tabindex="-1">3. Защита от многопоточных блокировок и взаимного ожидания <a class="header-anchor" href="#_3-защита-от-многопоточных-блокировок-и-взаимного-ожидания" aria-label="Permalink to &quot;3. Защита от многопоточных блокировок и взаимного ожидания&quot;">​</a></h3><p>Для предотвращения взаимных блокировок при одновременной работе интерфейса, фонового сборщика и интеллектуального ассистента в ядре активированы системные директивы:</p><ul><li>Таймаут ожидания освобождения базы увеличен до 5 секунд (<code>PRAGMA busy_timeout = 5000;</code>);</li><li>Включен строгий аппаратный контроль связей внешних ключей (<code>PRAGMA foreign_keys = ON;</code>);</li><li>Режим синхронизации с диском переведен на безопасный стандарт <code>PRAGMA synchronous = NORMAL;</code>, гарантирующий баланс высокой скорости и физической надежности.</li></ul><hr><h2 id="цеховои-регламент-защиты-информации" tabindex="-1">Цеховой регламент защиты информации <a class="header-anchor" href="#цеховои-регламент-защиты-информации" aria-label="Permalink to &quot;Цеховой регламент защиты информации&quot;">​</a></h2><p>Для абсолютной уверенности в сохранности коммерческих данных выработайте два простых правила:</p><h3 id="_1-правило-«3-2-1»-в-практике-мастерскои" tabindex="-1">1. Правило «3-2-1» в практике мастерской <a class="header-anchor" href="#_1-правило-«3-2-1»-в-практике-мастерскои" aria-label="Permalink to &quot;1. Правило «3-2-1» в практике мастерской&quot;">​</a></h3><ul><li><strong>3 копии данных:</strong> основная рабочая база на компьютере + автоматические снимки в папке программы + регулярный внешний экспорт.</li><li><strong>2 разных типа носителей:</strong> внутренний накопитель компьютера и внешний съемный диск или карта памяти.</li><li><strong>1 удаленная копия:</strong> зашифрованный ZIP-архив экосистемы, загруженный в доверенное защищенное облачное хранилище или на домашний сервер.</li></ul><h3 id="_2-переезд-на-новыи-рабочии-компьютер" tabindex="-1">2. Переезд на новый рабочий компьютер <a class="header-anchor" href="#_2-переезд-на-новыи-рабочии-компьютер" aria-label="Permalink to &quot;2. Переезд на новый рабочий компьютер&quot;">​</a></h3><p>Чтобы перенести всю мастерскую на новое рабочее место без потерь:</p><ol><li>На старом компьютере откройте <strong>«Файл» ➔ «Экспорт данных...» ➔ «Полная резервная копия системы (.zip)»</strong> и отметьте все компоненты;</li><li>Сохраните архив на съемный накопитель;</li><li>Установите ОмниКрафт ЕРП на новый компьютер и запустите чистую программу;</li><li>Выберите <strong>«Файл» ➔ «Импорт данных...» ➔ «Восстановление системы из бэкапа (.zip)»</strong> и укажите ваш файл архива;</li><li>Программа восстановит все пространства, остатки, рецепты, фотографии и историю, после чего перезагрузится в полностью настроенное рабочее состояние.</li></ol><hr><h2 id="вопросы-и-разбор-нештатных-ситуации-при-резервном-копировании" tabindex="-1">Вопросы и разбор нештатных ситуаций при резервном копировании <a class="header-anchor" href="#вопросы-и-разбор-нештатных-ситуации-при-резервном-копировании" aria-label="Permalink to &quot;Вопросы и разбор нештатных ситуаций при резервном копировании&quot;">​</a></h2><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">Что делать, если программа сообщает об ошибке доступа к папке архивов?</summary><div class="faq-content"><p>Обычно это вызвано блокировкой папки антивирусным ПО или нехваткой прав на запись в системный каталог <code>%APPDATA%\\OmniCraft\\backups\\</code>. Проверьте свободное место на системном диске C:, добавьте папку программы в доверенную зону вашего защитного ПО и перезапустите ОмниКрафт ЕРП от имени текущего пользователя (запуск от Администратора не требуется).</p></div></details><details class="faq-item"><summary class="faq-summary">Как восстановить учет, если файл ZIP-архива повреждён при копировании?</summary><div class="faq-content"><p>Если внешний архив не открывается из-за сбоя флешки, воспользуйтесь встроенным пунктом меню <b>«Файл» ➔ «Восстановить из автосохранения...»</b>. Программа хранит скользящую тройку последних завершений сессий (<code>auto_close_1.zip</code> ... <code>auto_close_3.zip</code>) и ежедневный снимок. Выберите контрольную точку за предыдущий рабочий день для отката состояния.</p></div></details><details class="faq-item"><summary class="faq-summary">Что произойдет при накате резервной копии от более старой версии программы?</summary><div class="faq-content"><p>При импорте архива движок СУБД считывает манифест версий <code>backup_manifest.json</code>. Если архив создан на ранней версии ОмниКрафт ЕРП, встроенный механизм миграций автоматически применит недостающие скрипты обновления таблиц. Если же архив создан на более новой версии, чем установлена сейчас, программа выдаст предупреждение с предложением сначала обновить приложение во избежание повреждения структур базы.</p></div></details></div>',66))])}const k=i(n,[["render",p]]);export{q as __pageData,k as default};
